import math
from numbers import Real

PI = 3.14159


def _number(value, name):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise TypeError(f"{name} must be a real number")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{name} must be finite")
    return result


def pipe_metrics(outer_radius, inner_radius, length):
    outer = _number(outer_radius, "outer_radius")
    inner = _number(inner_radius, "inner_radius")
    size = _number(length, "length")
    if outer <= 0:
        raise ValueError("outer_radius must be positive")
    if inner < 0 or inner >= outer:
        raise ValueError("inner_radius is out of range")
    if size < 0:
        raise ValueError("length must be non-negative")
    volume = PI * (outer ** 2 - inner ** 2) * size
    lateral_area = 2 * PI * outer * size
    return float(volume), float(lateral_area)

